const [query, setQuery] = useState('');
const [tab, setTab] = useState('all');

const results = useMemo(() => {
  const needle = query.trim().toLowerCase();
  return corpus.filter(
    (item) =>
      (tab === 'all' || item.kind === tab) &&
      (needle === '' || item.title.toLowerCase().includes(needle))
  );
}, [query, tab]);

return (
  <Panelside>
    <Panelside.Panel>
      <Panelside.Header title="Assistant" action={<Panelside.SearchTrigger />} />
      <Panelside.Content>{history}</Panelside.Content>
    </Panelside.Panel>

    <Panelside.Scene>{app}</Panelside.Scene>

    <Panelside.SearchSheet
      value={query}
      onValueChange={setQuery}
      tab={tab}
      onTabChange={setTab}
    >
      <Panelside.SearchTabs>
        <Panelside.SearchTab value="all" icon={<SparklesIcon size={16} />}>All</Panelside.SearchTab>
        <Panelside.SearchTab value="chats" icon={<MessageCircleIcon size={16} />}>Chats</Panelside.SearchTab>
        <Panelside.SearchTab value="images" icon={<ImageIcon size={16} />}>Images</Panelside.SearchTab>
        <Panelside.SearchTab value="documents" icon={<FileIcon size={16} />}>Documents</Panelside.SearchTab>
      </Panelside.SearchTabs>

      <Panelside.SearchResults>
        {results.map((item) => (
          <Panelside.SearchResult
            key={item.id}
            media={<FileIcon size={18} />}
            title={item.title}
            description={item.kind}
            onPress={() => open(item)}
          />
        ))}
      </Panelside.SearchResults>

      {/* The sheet draws the dismiss ✕ above the tabs itself. */}
      <Panelside.SearchField placeholder="Search chats, images and files" />
    </Panelside.SearchSheet>
  </Panelside>
);

function SceneTitle() {
  const { progress, toggle } = usePanelside();

  const style = useAnimatedStyle(() => ({
    opacity: 1 - progress.value,
    transform: [{ translateY: progress.value * -8 }],
  }));

  return (
    <Animated.View style={style}>
      <Text size="lg" weight="semibold">Migrating the design tokens</Text>
    </Animated.View>
  );
}
